export const updateArticleValidator: ValidationChain[] = [ param('id') .isMongoId() .withMessage('Invalid article ID'), body('title') .optional() .trim() .isLength({ max: 200 }) .withMessage('Title cannot exceed 200 characters'), body('subtitle') .optional() .trim() .isLength({ max: 300 }) .withMessage('Subtitle cannot exceed 300 characters'), body('content') .optional() .trim() .notEmpty() .withMessage('Content cannot be empty'), body('tags') .optional() .isArray() .withMessage('Tags must be an array') ];
// Comment validators export const createCommentValidator: ValidationChain[] = [ body('content') .trim() .notEmpty() .withMessage('Comment content is required') .isLength({ max: 2000 }) .withMessage('Comment cannot exceed 2000 characters'), body('articleId') .isMongoId() .withMessage('Invalid article ID'), body('parentCommentId') .optional() .isMongoId() .withMessage('Invalid parent comment ID') ];
// Category validators export const createCategoryValidator: ValidationChain[] = [ body('name') .trim() .notEmpty() .withMessage('Category name is required') .isLength({ max: 50 }) .withMessage('Category name cannot exceed 50 characters'), body('description') .optional() .trim() .isLength({ max: 300 }) .withMessage('Description cannot exceed 300 characters') ];
